1	// Differential probe harness for /workspace/dataset/test16_executable
2	// Usage:
3	//   node /workspace/tools/probe.mjs -e 'line1\nline2'      # md1(): convert ONE snippet, show html1
4	//   node /workspace/tools/probe.mjs --raw 'literal text'   # no backslash-escape interpretation
5	//   node /workspace/tools/probe.mjs --json '["snip1","snip2"]'   # batch, JSON in / JSON out
6	//   node /workspace/tools/probe.mjs --file snippets.json         # batch from file (JSON array)
7	//   node /workspace/tools/probe.mjs --full a b c d e             # full 5-arg program output
8	import { spawnSync } from 'node:child_process';
9	import { readFileSync } from 'node:fs';
10	
11	const EXE = '/workspace/dataset/test16_executable';
12	const SENT = 'ZQXSENTINELB';
13	
14	export function runExe(a, b, c, d, e) {
15	  const r = spawnSync(EXE, ['--a', a, '--b', b, '--c', c, '--d', d, '--e', e], {
16	    encoding: 'utf8', maxBuffer: 1 << 28,
17	  });
18	  return { stdout: r.stdout ?? '', stderr: r.stderr ?? '', code: r.status };
19	}
20	
21	// Convert a single markdown snippet and return exactly markdown.markdown(snippet).
22	export function md1(src) {
23	  const { stdout, code, stderr } = runExe(src, SENT, 'C', 'D', 'E');
24	  if (code !== 0) return { error: true, code, stderr };
25	  const marker = '\n<p>' + SENT + '</p>\n';
26	  const i = stdout.indexOf(marker);
27	  if (i < 0) return { error: true, code, stderr: 'sentinel not found', stdout };
28	  return { html: stdout.slice(0, i) };
29	}
30	
31	function unescape(s) {
32	  let out = '';
33	  for (let i = 0; i < s.length; i++) {
34	    if (s[i] === '\\' && i + 1 < s.length) {
35	      const c = s[++i];
36	      if (c === 'n') out += '\n';
37	      else if (c === 't') out += '\t';
38	      else if (c === 'r') out += '\r';
39	      else if (c === '\\') out += '\\';
40	      else { out += '\\'; out += c; }
41	    } else out += s[i];
42	  }
43	  return out;
44	}
45	
46	const argv = process.argv.slice(2);
47	if (argv.length) {
48	  const mode = argv[0];
49	  if (mode === '--full') {
50	    const [, a, b, c, d, e] = argv;
51	    const r = runExe(a ?? '', b ?? '', c ?? '', d ?? '', e ?? '');
52	    process.stdout.write(r.stdout);
53	    if (r.stderr) process.stderr.write(r.stderr);
54	    process.exitCode = r.code ?? 0;
55	  } else if (mode === '--json' || mode === '--file') {
56	    const src = mode === '--file' ? readFileSync(argv[1], 'utf8') : argv[1];
57	    const list = JSON.parse(src);
58	    const out = list.map((s) => {
59	      const r = md1(s);
60	      return { input: s, output: r.html ?? null, error: r.error ? (r.stderr || 'err') : undefined };
61	    });
62	    process.stdout.write(JSON.stringify(out, null, 1) + '\n');
63	  } else {
64	    const raw = mode === '--raw';
65	    const text = raw ? argv[1] : unescape(mode === '-e' ? argv[1] : mode);
66	    const r = md1(text);
67	    if (r.error) { process.stderr.write('ERROR ' + JSON.stringify(r) + '\n'); process.exitCode = 1; }
68	    else {
69	      process.stdout.write('INPUT_JSON:  ' + JSON.stringify(text) + '\n');
70	      process.stdout.write('OUTPUT_JSON: ' + JSON.stringify(r.html) + '\n');
71	      process.stdout.write('OUTPUT_RAW:\n⟦' + r.html + '⟧\n');
72	    }
73	  }
74	}
