// Multiplexed probe harness: converts MANY snippets in ONE executable run.
// Usage: node /workspace/tools/fast.mjs snippets.json [chunkSize]
// Prints JSON [{input, output}]  (output = html for that snippet alone)
// Caveat: snippets share one document, so reference definitions leak between
// snippets and unterminated blocks can swallow the separator. Verified against
// probe.mjs (one-process-per-snippet) for paragraph-only snippets.
import { spawnSync } from 'node:child_process';
import { readFileSync } from 'node:fs';

const EXE = '/workspace/dataset/test16_executable';
const SENT = 'ZQXSENTINELB';
const SEP = 'QXSEPQX';

function runDoc(src) {
  const r = spawnSync(EXE, ['--a', src, '--b', SENT, '--c', 'C', '--d', 'D', '--e', 'E'], {
    encoding: 'utf8', maxBuffer: 1 << 28,
  });
  const stdout = r.stdout ?? '';
  const marker = '\n<p>' + SENT + '</p>\n';
  const i = stdout.indexOf(marker);
  if (i < 0) throw new Error('sentinel missing: ' + JSON.stringify(stdout.slice(0, 400)) + ' stderr=' + r.stderr);
  return stdout.slice(0, i);
}

function trim1(s) {
  if (s.startsWith('\n')) s = s.slice(1);
  if (s.endsWith('\n')) s = s.slice(0, -1);
  return s;
}

export function mdMany(list, chunk = 120) {
  const res = [];
  for (let i = 0; i < list.length; i += chunk) {
    const part = list.slice(i, i + chunk);
    const doc = part.join('\n\n' + SEP + '\n\n');
    const html = runDoc(doc);
    const pieces = html.split('<p>' + SEP + '</p>');
    if (pieces.length !== part.length) {
      // fall back to one-at-a-time for this chunk
      for (const s of part) res.push(trim1(runDoc(s)));
    } else {
      for (const p of pieces) res.push(trim1(p));
    }
  }
  return res;
}

const argv = process.argv.slice(2);
if (argv.length) {
  const list = JSON.parse(readFileSync(argv[0], 'utf8'));
  const chunk = argv[1] ? parseInt(argv[1], 10) : 120;
  const outs = mdMany(list, chunk);
  process.stdout.write(JSON.stringify(list.map((s, i) => ({ input: s, output: outs[i] })), null, 1) + '\n');
}

