// Decode observed outputs for template "[T](..." into structured tuples,
// then compare against a candidate JS implementation of getLink().
import { readFileSync } from 'node:fs';

export function unescAttr(s) {
  return s.replace(/&quot;/g, '"').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/&#10;/g, '\n').replace(/&amp;/g, '&');
}
export function unescText(s) {
  return s.replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&amp;/g, '&');
}

export function decode(input, output) {
  // expects <p>...</p>
  if (!output.startsWith('<p>') || !output.endsWith('</p>')) return { weird: true, output };
  const body = output.slice(3, -4);
  if (!body.startsWith('<a href="')) return { handled: false, body };
  let i = 9;
  let j = body.indexOf('"', i);
  const href = unescAttr(body.slice(i, j));
  let k = j + 1;
  let title = null;
  if (body.startsWith(' title="', k)) {
    k += 8;
    const e = body.indexOf('"', k);
    title = unescAttr(body.slice(k, e));
    k = e + 1;
  }
  if (body[k] !== '>') return { weird: true, output };
  k++;
  const close = body.indexOf('</a>', k);
  const text = body.slice(k, close);
  const rest = unescText(body.slice(close + 4));
  const end = input.length - rest.length;
  return { handled: true, href, title, text, rest, end };
}

const rows = JSON.parse(readFileSync(process.argv[2], 'utf8'));
const dec = rows.map((r) => ({ input: r.input, output: r.output, d: decode(r.input, r.output) }));
if (process.argv[3] === '--dump') {
  for (const r of dec) {
    console.log(JSON.stringify(r.input), '=>', JSON.stringify(r.d));
  }
}
export default dec;

